DROP TABLE IF EXISTS `arcs`;
CREATE TABLE `arcs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `japanese_name` varchar(255) DEFAULT '',
  `arc_number` int(11) NOT NULL DEFAULT 0,
  `saga` varchar(255) DEFAULT '',
  `chapters` varchar(50) DEFAULT '',
  `manga_start_chapter` int(11) DEFAULT NULL,
  `manga_end_chapter` int(11) DEFAULT NULL,
  `manga_start_date` date DEFAULT NULL,
  `manga_end_date` date DEFAULT NULL,
  `anime_start_episode` int(11) DEFAULT NULL,
  `anime_end_episode` int(11) DEFAULT NULL,
  `anime_start_date` date DEFAULT NULL,
  `anime_end_date` date DEFAULT NULL,
  `episodes` varchar(50) DEFAULT '',
  `location` varchar(255) DEFAULT NULL,
  `timeline_position` varchar(50) DEFAULT 'Pre-Timeskip',
  `major_deaths` text DEFAULT NULL,
  `tragedy_meter` int(11) DEFAULT 0,
  `hype_rating` int(11) DEFAULT 0,
  `lore_importance` varchar(50) DEFAULT 'Normal',
  `key_villains` text DEFAULT NULL,
  `major_events` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image` varchar(500) DEFAULT '',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_saga` (`saga`),
  KEY `idx_arc_number` (`arc_number`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

