INSERT INTO `article_revisions` VALUES (1,1,1,'Monkey D. Luffy','<p>Captain of the Straw Hat Pirates.</p>','','2025-01-15 02:00:00','Initial draft'),(2,1,2,'Monkey D. Luffy','<p>Captain of the Straw Hat Pirates. He ate the Gomu Gomu no Mi.</p>','','2025-02-20 08:00:00','Added Devil Fruit info'),(3,1,1,'Monkey D. Luffy','<p>Captain of the Straw Hat Pirates. He ate the Gomu Gomu no Mi. His bounty is 3,000,000,000.</p>','','2025-03-01 03:00:00','Updated bounty'),(4,1,2,'Monkey D. Luffy','<p>Captain of the Straw Hat Pirates. He ate the Gomu Gomu no Mi, a mythical Zoan type.</p>','','2025-03-20 06:30:00','Corrected fruit type'),(5,3,3,'Gomu Gomu no Mi','<p>A Paramecia-type Devil Fruit.</p>','','2025-03-10 04:00:00','Initial article'),(6,3,2,'Gomu Gomu no Mi','<p>A Paramecia-type Devil Fruit that grants rubber properties.</p>','','2025-04-05 01:15:00','Added details');
