DROP TABLE IF EXISTS `chapters`;
CREATE TABLE `chapters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `arc_id` int(11) NOT NULL,
  `chapter_number` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `release_date` date DEFAULT NULL,
  `anime_adaptation_date` date DEFAULT NULL,
  `volume` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `chapter_number` (`chapter_number`),
  KEY `arc_id` (`arc_id`),
  CONSTRAINT `chapters_ibfk_1` FOREIGN KEY (`arc_id`) REFERENCES `arcs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
