DROP TABLE IF EXISTS `characters`;
CREATE TABLE `characters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `alias` varchar(255) DEFAULT NULL,
  `japanese_name` varchar(255) DEFAULT '',
  `romanji` varchar(255) DEFAULT '',
  `affiliation` varchar(255) DEFAULT '',
  `position` varchar(255) DEFAULT NULL,
  `origin` varchar(255) DEFAULT NULL,
  `first_appearance` varchar(255) DEFAULT NULL,
  `height` varchar(50) DEFAULT NULL,
  `birthday` varchar(20) DEFAULT NULL,
  `danger_level` varchar(50) DEFAULT 'Normal',
  `bounty` bigint(20) DEFAULT 0,
  `status` varchar(100) DEFAULT 'Alive',
  `description` text DEFAULT NULL,
  `manga_debut_chapter` int(11) DEFAULT NULL,
  `manga_debut_date` date DEFAULT NULL,
  `anime_debut_episode` int(11) DEFAULT NULL,
  `anime_debut_date` date DEFAULT NULL,
  `image` varchar(500) DEFAULT '',
  `debut_arc` varchar(255) DEFAULT '',
  `haki_types` varchar(255) DEFAULT NULL,
  `devil_fruit` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `debut_arc_id` int(11) DEFAULT NULL,
  `devil_fruit_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_affiliation` (`affiliation`),
  KEY `idx_debut_arc` (`debut_arc_id`),
  KEY `idx_devil_fruit` (`devil_fruit_id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

