DROP TABLE IF EXISTS `devil_fruits`;
CREATE TABLE `devil_fruits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `japanese_name` varchar(255) DEFAULT '',
  `type` enum('Paramecia','Zoan','Logia','Mythical Zoan','Ancient Zoan','Special Paramecia','Unknown') DEFAULT 'Unknown',
  `description` text DEFAULT NULL,
  `current_holder` varchar(255) DEFAULT '',
  `awakening` varchar(20) DEFAULT 'No',
  `debut_chapter` varchar(100) DEFAULT NULL,
  `strength_level` varchar(50) DEFAULT 'C',
  `weakness` varchar(255) DEFAULT NULL,
  `combat_rating` int(11) DEFAULT 0,
  `rarity_meter` int(11) DEFAULT 0,
  `threat_level` varchar(50) DEFAULT 'Low',
  `image` varchar(500) DEFAULT '',
  `created_at` datetime DEFAULT current_timestamp(),
  `current_holder_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `idx_type` (`type`),
  KEY `idx_holder` (`current_holder_id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

