--

LOCK TABLES `devil_fruits` WRITE;
INSERT INTO `devil_fruits` VALUES (1,'Gomu Gomu no Mi','pé¦pâápé¦pâápü«s«ƒ','Paramecia','A rubber body. The user\'s body gains the properties of rubber, allowing incredible stretching. Its true name is Hito Hito no Mi, Model: Nika.','Monkey D. Luffy','Yes','Chapter 1','S','Seawater, Seastone',65,30,'Low','assets/images/devil_fruits/gomu-gomu-no-mi.png','2026-05-30 13:50:21',1),(2,'Mera Mera no Mi','pâípâ¬pâípâ¬pü«s«ƒ','Logia','Allows the user to create, control, and turn into fire. One of the most powerful Logia fruits.','Sabo','No','Chapter 1','C','Seawater, Seastone',15,10,'Minimal','assets/images/devil_fruits/mera-mera-no-mi.png','2026-05-30 13:50:21',NULL),(3,'Yami Yami no Mi','pâñpâƒpâñpâƒpü«s«ƒ','Logia','Allows the user to create and control darkness. Can nullify other Devil Fruit powers and pull in anything.','Marshall D. Teach','No','Chapter 3','C','Seawater, Seastone',10,10,'Minimal','assets/images/devil_fruits/yami-yami-no-mi.png','2026-05-30 13:50:21',14),(4,'Gura Gura no Mi','pé¦pâ¬pé¦pâ¬pü«s«ƒ','Paramecia','Allows the user to create powerful shockwaves that can destroy anything. Known as a power capable of destroying the world.','Edward Newgate','Unknown','Chapter 49','B','Seawater, Seastone',30,40,'Moderate','assets/images/devil_fruits/gura-gura-no-mi.png','2026-05-30 13:50:21',23),(5,'Ope Ope no Mi','pé¬pâÜpé¬pâÜpü«s«ƒ','Paramecia','Allows the user to create a spherical space where they have complete control, able to manipulate anything inside it.','Trafalgar D. Water Law','Yes','Chapter 50','A','Seawater, Seastone',75,60,'Dangerous','assets/images/devil_fruits/ope-ope-no-mi.png','2026-05-30 13:50:21',17),(6,'Hana Hana no Mi','pâÅpâèpâÅpâèpü«s«ƒ','Paramecia','Allows the user to sprout duplicate body parts anywhere, from any surface.','Nico Robin','No','Chapter 134','D','Seawater, Seastone',5,20,'Harmless','assets/images/devil_fruits/hana-hana-no-mi.png','2026-05-30 13:50:21',7),(7,'Ito Ito no Mi','péñpâêpéñpâêpü«s«ƒ','Paramecia','Allows the user to create and control nearly invisible threads for attacking and manipulation.','Doflamingo','No','Chapter 184','S','Seawater, Seastone, Darkness',88,85,'Critical','assets/images/devil_fruits/ito-ito-no-mi.png','2026-05-30 13:50:21',27),(8,'Soru Soru no Mi','pé+pâ½pé+pâ½pü«s«ƒ','Paramecia','Allows the user to manipulate souls, including extracting them and placing them into objects (Homies).','Charlotte Linlin','Yes','Chapter 234','SS','Seawater, Seastone, Tremor',95,90,'Catastrophic','assets/images/devil_fruits/soru-soru-no-mi.png','2026-05-30 13:50:21',16),(9,'Hito Hito no Mi','pâÆpâêpâÆpâêpü«s«ƒ','Mythical Zoan','A mythical Zoan that allows the user to transform into a giant golden Buddha. Sengoku\'s fruit.','Sengoku','Unknown','Chapter 252','SS','Seawater, Seastone, Darkness',95,95,'Catastrophic','assets/images/devil_fruits/hito-hito-no-mi.png','2026-05-30 13:50:21',21),(10,'Moku Moku no Mi','pâópé»pâópé»pü«s«ƒ','Logia','Allows the user to create, control, and turn into smoke.','Smoker','No','Chapter 387','A','Seawater, Seastone, Haki',78,65,'High','assets/images/devil_fruits/moku-moku-no-mi.png','2026-05-30 13:50:21',25),(11,'Mero Mero no Mi','pâípâ¡pâípâ¡pü«s«ƒ','Paramecia','Allows the user to turn people who have lustful thoughts into stone.','Boa Hancock','Yes','Chapter 432','SS','Seawater, Seastone, Haki',97,95,'Catastrophic','assets/images/devil_fruits/mero-mero-no-mi.png','2026-05-30 13:50:21',26),(12,'Hie Hie no Mi','pâÆpé¿pâÆpé¿pü«s«ƒ','Logia','Allows the user to create, control, and turn into ice.','Kuzan (Aokiji)','Unknown','Chapter 460','SS','Seawater, Seastone, Haki',96,92,'Catastrophic','assets/images/devil_fruits/hie-hie-no-mi.png','2026-05-30 13:50:21',NULL),(13,'Pika Pika no Mi','pâöpé½pâöpé½pü«s«ƒ','Logia','Allows the user to create, control, and turn into light.','Borsalino (Kizaru)','No','Chapter 464','B','Seawater, Seastone',40,25,'Moderate','assets/images/devil_fruits/pika-pika-no-mi.png','2026-05-30 13:50:21',NULL),(14,'Goro Goro no Mi','pé¦pâ¡pé¦pâ¡pü«s«ƒ','Logia','Allows the user to create, control, and turn into lightning.','Enel','No','Chapter 465','A','Seawater, Seastone, Fire',70,50,'Dangerous','assets/images/devil_fruits/goro-goro-no-mi.png','2026-05-30 13:50:21',NULL),(15,'Suna Suna no Mi','pé¦pâèpé¦pâèpü«s«ƒ','Logia','Allows the user to create, control, and turn into sand. Can drain moisture from anything.','Crocodile','No','Chapter 504','A','Seawater, Seastone',72,55,'Dangerous','assets/images/devil_fruits/suna-suna-no-mi.png','2026-05-30 13:50:21',NULL),(16,'Bara Bara no Mi','pâÉpâ¬pâÉpâ¬pü«s«ƒ','Paramecia','Allows the user to split their body into pieces and control each part independently.','Buggy','No','Chapter 516','S','Seawater, Seastone, Haki',85,80,'Critical','assets/images/devil_fruits/bara-bara-no-mi.png','2026-05-30 13:50:21',NULL),(17,'Mizu Mizu no Mi','known as Sui Sui no Mi','Paramecia','Allows the user to swim through solid surfaces as if they were water.','Senor Pink','No','Chapter 544','B','Seawater, Seastone',35,20,'Moderate','assets/images/devil_fruits/mizu-mizu-no-mi.svg','2026-05-30 13:50:21',NULL),(18,'Nagi Nagi no Mi','pâèpé«pâèpé«pü«s«ƒ','Paramecia','Allows the user to create a silent field, blocking all sound around them.','Donquixote Rosinante','Yes','Chapter 697','SS','Seawater, Seastone, Haki',92,88,'Catastrophic','assets/images/devil_fruits/nagi-nagi-no-mi.png','2026-05-30 13:50:21',NULL),(19,'Tori Tori no Mi, Model: Phoenix','pâêpâ¬pâêpâ¬pü«s«ƒ pâópâçpâ½n+Ñpâòpéºpâïpââpé»pé¦','Mythical Zoan','Allows the user to transform into a phoenix with regenerative blue flames.','Marco','No','Chapter 753','A','Seawater, Seastone',75,60,'Dangerous','assets/images/devil_fruits/tori-tori-no-mi-model-phoenix.png','2026-05-30 13:50:21',NULL),(20,'Inu Inu no Mi, Model: Okuchi no Makami','péñpâîpéñpâîpü«s«ƒ pâópâçpâ½n+ÑsñºsÅúpü«tÑP','Mythical Zoan','Allows the user to transform into a wolf deity with ice powers.','Yamato','No','Chapter 766','A','Seawater, Seastone, Haki',72,50,'Dangerous','assets/images/devil_fruits/inu-inu-no-mi-model-okuchi-no-makami.png','2026-05-30 13:50:21',NULL),(21,'Maki Maki no Mi','known as Buki Buki no Mi','Paramecia','Allows the user to turn their body into weapons.','Baby 5','Yes','Chapter 924','SS','Seawater, Seastone, Haki',95,90,'Catastrophic','assets/images/devil_fruits/maki-maki-no-mi.png','2026-05-30 13:50:21',NULL),(22,'Fuwa Fuwa no Mi','pâòpâ»pâòpâ»pü«s«ƒ','Paramecia','Allows the user to make objects float and levitate freely.','Shiki','No','Chapter 997','SS','Seawater, Seastone, Haki',94,95,'Catastrophic','assets/images/devil_fruits/fuwa-fuwa-no-mi.png','2026-05-30 13:50:21',NULL),(23,'Jiki Jiki no Mi','pé+pé¡pé+pé¡pü«s«ƒ','Paramecia','Allows the user to magnetize objects and control metal.','Eustass Kid','No','Chapter 1044','SSS','Seawater, Seastone',98,99,'Legendary','assets/images/devil_fruits/jiki-jiki-no-mi.png','2026-05-30 13:50:21',18),(24,'Suke Suke no Mi','pé¦pé¦pé¦pé¦pü«s«ƒ','Paramecia','Allows the user to turn themselves and anything they touch invisible.','Shiryu','Unknown','Chapter 1063','SS','Seawater, Seastone',92,90,'Catastrophic','assets/images/devil_fruits/suke-suke-no-mi.png','2026-05-30 13:50:21',NULL),(25,'Kage Kage no Mi','pé½pé¦pé½pé¦pü«s«ƒ','Paramecia','Allows the user to manipulate shadows, including stealing them and placing them into corpses.','Gecko Moria','No','Unknown','C','Seawater, Seastone',30,15,'Low','assets/images/devil_fruits/kage-kage-no-mi.png','2026-05-30 13:50:21',NULL);
