DROP TABLE IF EXISTS `episodes`;
CREATE TABLE `episodes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `arc_id` int(11) NOT NULL,
  `episode_number` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `air_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `episode_number` (`episode_number`),
  KEY `arc_id` (`arc_id`),
  CONSTRAINT `episodes_ibfk_1` FOREIGN KEY (`arc_id`) REFERENCES `arcs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

