DROP TABLE IF EXISTS `theories`;
CREATE TABLE `theories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `spoiler_level` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `user_id` (`user_id`),
  FULLTEXT KEY `ft_theories` (`title`,`content`),
  CONSTRAINT `theories_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
--

LOCK TABLES `theories` WRITE;
INSERT INTO `theories` VALUES (1,1,'The Will of D.','will-of-d','<p>The Will of D. is passed down through generations.</p>','approved',0,'2025-02-15 10:00:00','2026-05-31 08:19:16'),(2,2,'The True Nature of the One Piece','true-nature-one-piece','<p>The One Piece is not just treasure but a message from Joy Boy that will change the world order forever. It explains the truth of the Void Century and the ancient weapons.</p>','approved',0,'2026-06-01 11:31:21','2026-06-01 11:31:21'),(3,2,'Who Is Imu? The True Ruler of the World','who-is-imu','<p>Imu sits on the Empty Throne as the secret ruler of the World Government. They may be centuries old, kept alive by the Ope Ope no Mi\'s eternal youth surgery.</p>','approved',1,'2026-06-01 11:31:26','2026-06-01 11:31:26'),(4,2,'The Identity of Joy Boy','identity-joy-boy','<p>Joy Boy was the first pirate and the original owner of the Gomu Gomu no Mi. Luffy is his reincarnation, destined to fulfill the promise left void centuries ago.</p>','approved',0,'2026-06-01 11:31:29','2026-06-01 11:31:29'),(5,2,'Shanks and the Holy Knights','shanks-holy-knights','<p>Shanks\' connection to the Figarland family and the Holy Knights suggests he may have been a former member, explaining his access to Mariejois and political power.</p>','approved',0,'2026-06-01 11:31:33','2026-06-01 11:31:33'),(6,2,'Zoro Left Eye and the Curse of Ashura','zoro-left-eye-ashura','<p>Zoro closed left eye may hide a powerful demonic force tied to the Ashura curse.</p>','approved',1,'2026-06-01 11:32:14','2026-06-01 11:32:14'),(7,2,'The God Valley Incident Explained','god-valley-incident','<p>The God Valley Incident was a three-way battle between Rocks D. Xebec the Roger Pirates and the Marines.</p>','approved',0,'2026-06-01 11:32:19','2026-06-01 11:32:19'),(8,2,'Who Is the Traitor on the Straw Hat Grand Fleet?','straw-hat-grand-fleet-traitor','<p>One of the seven captains of the Straw Hat Grand Fleet may be a spy.</p>','approved',1,'2026-06-01 11:32:22','2026-06-01 11:32:22'),(9,2,'The Moon and the Minks: A Lunar Connection','moon-minks-lunar','<p>The Minks and the prehistoric civilization of the Moon share a common ancestor.</p>','approved',0,'2026-06-01 11:32:26','2026-06-01 11:32:26'),(10,2,'Blackbeard Third Devil Fruit','blackbeard-third-devil-fruit','<p>Blackbeard will obtain a third devil fruit to complete his trio of powers.</p>','approved',0,'2026-06-01 11:32:30','2026-06-01 11:32:30'),(11,2,'The True Purpose of the Ancient Weapons','ancient-weapons-purpose','<p>Pluton Poseidon and Uranus were not weapons of destruction but tools designed to protect the world from an ancient threat.</p>','approved',0,'2026-06-01 11:33:27','2026-06-01 11:33:27');
UNLOCK TABLES;

