DROP TABLE IF EXISTS `timeline`;
CREATE TABLE `timeline` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `category` enum('manga','anime','character_debut','arc_release','legendary') DEFAULT 'legendary',
  `chapter_number` int(11) DEFAULT NULL,
  `episode_number` int(11) DEFAULT NULL,
  `release_date` date DEFAULT NULL,
  `character_id` int(11) DEFAULT NULL,
  `event_date` varchar(100) NOT NULL DEFAULT '',
  `manga_reference` varchar(255) DEFAULT NULL,
  `anime_reference` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `participants` varchar(255) DEFAULT NULL,
  `canon_status` varchar(50) DEFAULT 'Confirmed',
  `arc_id` int(11) DEFAULT NULL,
  `importance` varchar(50) DEFAULT 'Normal',
  `article_id` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_event_date` (`event_date`),
  KEY `arc_id` (`arc_id`),
  KEY `article_id` (`article_id`),
  CONSTRAINT `timeline_ibfk_1` FOREIGN KEY (`arc_id`) REFERENCES `arcs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `timeline_ibfk_2` FOREIGN KEY (`article_id`) REFERENCES `wiki_articles` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=545 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
--

