INSERT INTO `timeline` VALUES (19,'Gol D. Roger is executed at Logue Town','legendary',NULL,NULL,NULL,NULL,'April 25, 1524',NULL,NULL,'The Pirate King is executed, sparking the Great Pirate Era.',NULL,'Confirmed',6,'Normal',NULL,'2026-05-30 13:52:52'),(20,'Shanks gives Luffy his straw hat','legendary',NULL,NULL,NULL,NULL,'Approx. 1537',NULL,NULL,'Young Luffy meets Shanks in Foosha Village and receives his straw hat.',NULL,'Confirmed',NULL,'Normal',NULL,'2026-05-30 13:52:52'),(21,'Luffy sets sail from Foosha Village','legendary',NULL,NULL,NULL,NULL,'Approx. 1548',NULL,NULL,'Luffy begins his journey as a pirate at age 17.',NULL,'Confirmed',NULL,'Normal',NULL,'2026-05-30 13:52:52'),(22,'Luffy defeats Arlong','legendary',NULL,NULL,NULL,NULL,'1548',NULL,NULL,'Nami officially joins the Straw Hat Pirates.',NULL,'Confirmed',5,'Normal',NULL,'2026-05-30 13:52:56'),(23,'The Straw Hats reach the Grand Line','legendary',NULL,NULL,NULL,NULL,'1548',NULL,NULL,'The crew enters the Grand Line via Reverse Mountain.',NULL,'Confirmed',7,'Normal',NULL,'2026-05-30 13:52:56'),(24,'Crocodile defeated in Alabasta','legendary',NULL,NULL,NULL,NULL,'1548',NULL,NULL,'Robin officially joins the Straw Hats.',NULL,'Confirmed',11,'Normal',NULL,'2026-05-30 13:52:56'),(25,'Enel defeated, Skypiea liberated','legendary',NULL,NULL,NULL,NULL,'1548',NULL,NULL,'The crew rings the golden bell and proves the existence of sky islands.',NULL,'Confirmed',13,'Normal',NULL,'2026-05-30 13:53:00'),(26,'CP9 defeated, Robin rescued at Enies Lobby','legendary',NULL,NULL,NULL,NULL,'1548',NULL,NULL,'The Straw Hats declare war on the World Government.',NULL,'Confirmed',16,'Normal',NULL,'2026-05-30 13:53:00'),(27,'Brook joins the Straw Hats','legendary',NULL,NULL,NULL,NULL,'1549',NULL,NULL,'The crew gains their musician after defeating Gecko Moria.',NULL,'Confirmed',18,'Normal',NULL,'2026-05-30 13:53:00'),(28,'The Straw Hats separated at Sabaody','legendary',NULL,NULL,NULL,NULL,'1549',NULL,NULL,'Kuma sends each crew member