DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `role` enum('user','moderator','admin') NOT NULL DEFAULT 'user',
  `banned` tinyint(1) DEFAULT 0,
  `reputation_points` int(11) NOT NULL DEFAULT 0,
  `spoiler_tolerance` tinyint(4) NOT NULL DEFAULT 0,
  `bio` text DEFAULT NULL,
  `profile_theme` enum('pirate','marine','revolutionary','yonko') DEFAULT 'pirate',
  `avatar` varchar(255) DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL,
  `favorite_character` varchar(100) DEFAULT NULL,
  `favorite_arc` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

