DROP TABLE IF EXISTS `wiki_articles`;
CREATE TABLE `wiki_articles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `category` varchar(100) DEFAULT 'General',
  `views` int(11) DEFAULT 0,
  `last_edited_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `spoiler_level` tinyint(4) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `user_id` (`user_id`),
  FULLTEXT KEY `ft_articles` (`title`,`content`),
  CONSTRAINT `wiki_articles_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
--

LOCK TABLES `wiki_articles` WRITE;
INSERT INTO `wiki_articles` VALUES (1,1,'Monkey D. Luffy','monkey-d-luffy','<p>Captain of the Straw Hat Pirates. He ate the Gomu Gomu no Mi.</p>','Character',4,2,'2025-01-14 18:00:00','2026-05-31 02:12:07','approved',0),(2,1,'Straw Hat Pirates','straw-hat-pirates','<p>A pirate crew from East Blue led by Monkey D. Luffy.</p>','Organization',0,NULL,'2025-01-31 16:00:00','2025-01-31 16:00:00','approved',0),(3,3,'Gomu Gomu no Mi','gomu-gomu-no-mi','<p>A Paramecia-type Devil Fruit that grants rubber properties.</p>','Devil Fruit',2,2,'2025-03-09 20:00:00','2026-05-31 01:40:46','approved',0),(4,2,'The Void Century','void-century','<p>The Void Century is a 100-year gap in world history that the World Government has erased. Only the Poneglyphs hold the truth.</p>','History',0,NULL,'2026-06-01 03:32:34','2026-06-01 03:32:34','approved',1),(5,2,'Haki: The Power of Will','haki-power-will','<p>Haki is a latent power that exists in all living beings. The three types are Observation Armament and Conqueror Haki.</p>','Science',0,NULL,'2026-06-01 03:32:39','2026-06-01 03:32:39','approved',0),(6,2,'The Ancient Kingdom','ancient-kingdom','<p>The Ancient Kingdom was a powerful civilization that existed during the Void Century. Its allies included Wano and the Giants of Elbaf.</p>','History',0,NULL,'2026-06-01 03:32:43','2026-06-01 03:32:43','approved',1),(7,2,'Poneglyphs: History in Stone','poneglyphs-history-stone','<p>Poneglyphs are ancient stone tablets inscribed with the history of the Void Century. Rio Poneglyph will reveal the true history.</p>','Technology',0,NULL,'2026-06-01 03:32:47','2026-06-01 03:32:47','approved',0),(8,2,'Wano Country: History and Culture','wano-country','<p>Wano Country is a isolated nation in the New World known for its samurai culture and the production of Seastone. It was closed off for centuries by the Shogun.</p>','History',0,NULL,'2026-06-01 03:32:52','2026-06-01 03:32:52','approved',0),(9,2,'The Road Poneglyphs and Laugh Tale','road-poneglyphs-laugh-tale','<p>Four Road Poneglyphs mark the location of Laugh Tale the final island of the Grand Line where the One Piece awaits.</p>','General',0,NULL,'2026-06-01 03:32:56','2026-06-01 03:32:56','approved',0),(10,2,'Devil Fruit Classifications','devil-fruit-classifications','<p>Devil Fruits are classified into three main types: Paramecia Zoan and Logia. Subtypes include Ancient and Mythical Zoans and Special Paramecia.</p>','Science',0,NULL,'2026-06-01 03:33:00','2026-06-01 03:33:00','approved',0),(11,2,'The Marines Organization','marines-organization','<p>The Marines are the naval military force of the World Government. Their headquarters moved from Marineford to the New World after the Paramount War.</p>','General',0,NULL,'2026-06-01 03:33:04','2026-06-01 03:33:04','approved',0),(12,2,'The Gorosei and the Elders','gorosei-elders','<p>The Gorosei are the five elder stars who govern the World Government below Imu. Each bears the name of a planet and likely possesses a devil fruit.</p>','History',0,NULL,'2026-06-01 03:33:08','2026-06-01 03:33:08','approved',1),(13,2,'The Three Ancient Weapons','three-ancient-weapons','<p>Pluton a battleship Poseidon the Sea Kings and Uranus a sky weapon are the three ancient weapons capable of immense destruction.</p>','Technology',0,NULL,'2026-06-01 03:33:12','2026-06-01 03:33:12','approved',0);
UNLOCK TABLES;


